```python
def binary_search(arr, x):
    l = 0
    r = len(arr) - 1
    while l <= r:
        m = l + (r - l) // 2
        if x == arr[m]:
            return m
        elif x > arr[m]:
            l = m + 1
        else:
            r = m - 1
    return -1
