def findSCS(str1, str2, m, n): 
    if m == 0: 
        return n 
    if n == 0: 
        return m 
    if str1[m - 1] == str2[n - 1]: 
        return 1 + findSCS(str1, str2, m - 1, n - 1) 
    else: 
        return 1 + min(findSCS(str1, str2, m, n - 1), 
                       findSCS(str1, str2, m - 1, n)) 

def SCS(str1, str2): 
    return findSCS(str1, str2, len(str1), len(str2))
